head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[image > M > setSrc]<br/>Image 컴포넌트의 src 속성을 설정합니다.",
    "validation" : [
        "Url(필수) 파라미터로 Image 컴포넌트에 표시할 이미지의 URL 을 설정합니다.",
        "Url(필수) 파라미터로 상대경로, 절대경로, 프로토콜 포함 경로를 설정할 수 있습니다.",
        "Url(필수) 파라미터로 'data:' 로 시작하는 Data URL 형식을 설정할 수 있습니다.",
        "Url(필수) 파라미터로 PNG, JPG, JPEG, GIF, SVG 등 웹브라우저가 지원하는 모든 이미지 파일을 설정할 수 있습니다.",
        "src 속성값은 기준 경로에 맞게 보정된 뒤 이미지 요청에 사용됩니다.",
        "경로 보정이 적용되므로 src 속성값과 요청되는 주소는 다를 수 있으며, 실제 주소는 getSrc() 메소드로 확인합니다.",
        "src 속성이 정상적으로 설정되면 화면에 표시되고 있는 이미지가 즉시 변경됩니다.",
        "ref 속성으로 바인딩된 상태에서 setSrc() 메소드로 이미지를 바꿔도 바인딩된 DataCollection 에 반영되지 않습니다.",
        "ref 속성으로 바인딩된 상태에서 데이터 선택이 변경되면 바인딩된 데이터값이 src 속성에 설정되고 해당 이미지가 화면에 표시됩니다.",
    ]
}



scwin.onpageload = function () {
    // 정적 select1 초기값 설정 (ref : 미설정 / Url 파라미터 : 절대경로 PNG)
    con_ref.setValue("");
    par_Url.setValue("/img/png.png");

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (scwin.target1) {
        scwin.target1.remove();
        scwin.target1 = null;
    }

    let cRef = con_ref.getValue();

    // ref 바인딩 시 이미지가 바로 표시되도록 행 0 을 선택한 상태로 시작한다
    dlt_image.setRowPosition(0);

    let lblRef = (cRef === '') ? '미설정' : cRef;

    $c.gcm.createLabel('label="[현재] ref = ' + lblRef + ' / 선언 src = /img/icon_M.png (setSrc 호출 전 표시 이미지)\n[절차] con 값 변경 -> Target 재생성 -> Url 파라미터 선택 -> setSrc 버튼 클릭\n[확인] 호출 전과 후의 표시 경로 및 렌더 크기 대비로 이미지가 즉시 바뀌는지 확인합니다\n[확인] ref 바인딩 전제 항목은 ref 를 설정해 재생성한 뒤 setSrc 버튼 -> DataList 행 선택 변경 버튼 순서로 확인합니다\n[참고] DataList 행 데이터 : 0 = /img/icon_F.png, 1 = /img/icon_calculator.png (ref 설정 시 선언 src 대신 행 0 데이터가 표시됩니다) / 프로토콜 포함 경로는 외부망 미연결 시 표시에 실패할 수 있으며 요청 주소로 확인합니다"', '', 'label1');

    // 조건 설정 (src 는 setSrc 호출 전 상태를 고정하기 위해 /img/icon_M.png 로 선언한다)
    let properties = {
        ref : cRef,
    };

    let cList = $c.gcm.createCList(properties);

    // src 를 고정값으로 지정해야 하므로 공통 함수($c.gcm.createBasicImage 는 src 가 /img/png.png 고정) 대신 직접 생성한다
    let grp_comp = $c.gcm.getTestGroup('');

    let strTarget = '<xf:image ' + $c.gcm.strNameSpace + ' ' + cList + ' src="/img/icon_M.png"></xf:image>';

    scwin.target1 = await $p.dynamicCreate("target1", "image", strTarget, grp_comp);

    // 이미지 로드 성공 / 실패가 확정된 후에 표시 상태를 관측할 수 있으므로 대기한다
    await scwin.waitImage();
}



// 이미지 로드(성공/실패) 확정 대기
scwin.waitImage = function () {
    return new Promise(function (resolve) {
        let img = scwin.target1.render;

        if (img.complete) {
            resolve();
            return;
        }

        img.addEventListener("load", resolve, { once : true });
        img.addEventListener("error", resolve, { once : true });
        setTimeout(resolve, 2000);
    });
}



// 긴 URL(Data URL 등) 축약
scwin.shortUrl = function (url) {
    return (url.length > 60) ? url.substring(0, 60) + " ...(전체 길이 " + url.length + ")" : url;
}



// 이미지 표시 여부 판정 (src 문자열이 아니라 로드 성공 여부로 판정, 크기는 getBox 로 병행 확인)
scwin.isShown = function () {
    let img = scwin.target1.render;
    return img.complete && img.naturalWidth > 0;
}



// 이미지 실측 크기 (원본 / 렌더 박스)
scwin.getBox = function () {
    let img = scwin.target1.render;

    return "원본 " + img.naturalWidth + "x" + img.naturalHeight + ", 렌더 " + img.offsetWidth + "x" + img.offsetHeight;
}



// Url 파라미터의 유형 (경로 유형 + 이미지 파일 형식 / Data URL)
scwin.getUrlType = function (pUrl) {
    if (pUrl.indexOf("data:") === 0) return 'Data URL';

    let kind = (pUrl.indexOf("://") > -1) ? '프로토콜 포함 경로' : (pUrl.charAt(0) === '/') ? '절대경로' : '상대경로';
    let idx = pUrl.lastIndexOf(".");

    return (idx < 0) ? kind : kind + " (" + pUrl.substring(idx + 1).toUpperCase() + ")";
}



// 바인딩된 DataCollection 의 현재 데이터값
scwin.getBindValue = function () {
    let pos = dlt_image.getRowPosition();

    return (pos < 0) ? "행 미선택" : dlt_image.getCellData(pos, "imgPath");
}



// setSrc 호출 및 validation 1 ~ 8 판정 출력
scwin.btn_setSrc_onclick = async function (e) {
    let bottom = wf_body_bottom.getObj("scwin");
    let img = scwin.target1.render;

    let pUrl = par_Url.getValue();
    let cRef = con_ref.getValue();

    // 호출 전 표시 상태 (실제 요청 주소는 getSrc() 로 확인)
    let beforeSrc = scwin.target1.getSrc();
    let beforeBox = scwin.getBox();

    // Url(필수) 파라미터로 src 속성 설정
    scwin.target1.setSrc(pUrl);

    await scwin.waitImage();

    let attrSrc = img.getAttribute("src");
    let realSrc = scwin.target1.getSrc();

    // [1~4] 설정한 URL / 유형(경로 유형 + 파일 형식 또는 Data URL) / 표시 상태
    bottom.setReturnValue("[1~4] setSrc 호출 -> Url 파라미터 : " + scwin.shortUrl(pUrl) + " / 유형 : " + scwin.getUrlType(pUrl) + " / 표시 : " + scwin.isShown() + " (" + scwin.getBox() + ")");

    // [5,6] 설정값 -> 보정된 속성값 -> getSrc() 실제 요청 주소 (Data URL 은 경로 보정 대상 아님)
    if (pUrl.indexOf("data:") !== 0) {
        bottom.setReturnValue("[5,6] 설정값 : " + pUrl + " -> 보정 속성값 : " + attrSrc + " -> getSrc() : " + realSrc + " / 설정값과 동일 : " + (pUrl === realSrc));
    }

    // [7] 호출 전 -> 후 표시 이미지 대비
    bottom.setReturnValue("[7] 호출 전 표시 : " + scwin.shortUrl(beforeSrc) + " (" + beforeBox + ") -> 호출 후 표시 : " + scwin.shortUrl(realSrc) + " (" + scwin.getBox() + ") / 즉시 변경 : " + (beforeSrc !== realSrc));

    // [8] ref 바인딩 상태일 때만 대상
    if (cRef !== '') {
        let bindValue = scwin.getBindValue();

        bottom.setReturnValue("[8] 화면 표시 경로 : " + scwin.shortUrl(realSrc) + " / 바인딩 DataCollection 값 : " + bindValue + " / DataCollection 반영 : " + (bindValue === pUrl));
    }
};



// DataList 선택 행 변경 및 validation 9 판정 출력
scwin.btn_setRowPosition_onclick = async function (e) {
    let bottom = wf_body_bottom.getObj("scwin");

    // ref 바인딩이 전제인 항목이므로 미설정 시 확인 방법을 안내한다
    if (con_ref.getValue() === '') {
        bottom.setReturnValue("[9] ref 를 data:dlt_image.imgPath 로 설정하고 Target 재생성 후 다시 클릭하세요.");
        return;
    }

    dlt_image.setRowPosition(1);

    await scwin.waitImage();

    let img = scwin.target1.render;

    bottom.setReturnValue("[9] DataList 선택 행 1 -> 바인딩 데이터값 : " + scwin.getBindValue() + " -> src 속성 : " + img.getAttribute("src") + " / 표시 : " + scwin.isShown() + " (" + scwin.getBox() + ")");
};
